import numpy as np
class _Frame: samp_freq = 16000; dither = 0.0
class _Mel: num_bins = 80
class FbankOptions:
    def __init__(self): self.frame_opts = _Frame(); self.mel_opts = _Mel()
class OnlineFbank:
    def __init__(self, options): self.options = options; self.parts = []; self.frames = np.zeros((0, 80))
    def accept_waveform(self, rate, wave): self.parts.append(np.asarray(wave, np.float32))
    def input_finished(self):
        wave = np.concatenate(self.parts); bins = self.options.mel_opts.num_bins
        count = max(0, 1 + (len(wave) - 400) // 160)
        frames = wave[np.arange(400)[None] + 160 * np.arange(count)[:, None]] * np.hamming(400)
        power = np.abs(np.fft.rfft(frames, 512)) ** 2
        mel = lambda hz: 2595 * np.log10(1 + hz / 700)
        edges = 700 * (10 ** (np.linspace(mel(20), mel(8000), bins + 2) / 2595) - 1)
        freqs = np.linspace(0, 8000, 257)
        bank = np.maximum(0, np.minimum((freqs[None] - edges[:-2, None]) / (edges[1:-1] - edges[:-2])[:, None], (edges[2:, None] - freqs[None]) / (edges[2:] - edges[1:-1])[:, None]))
        self.frames = np.log(np.maximum(power @ bank.T, 1e-10)).astype(np.float32)
    @property
    def num_frames_ready(self): return len(self.frames)
    def get_frame(self, index): return self.frames[index]
EOF_2
