import numpy as np
def v(n):
    o = b''
    while True:
        b = n & 0x7f; n >>= 7
        if n: o += bytes([b | 0x80])
        else: return o + bytes([b])
def ln(k, d): return v(k << 3 | 2) + v(len(d)) + d
def i(k, n): return v(k << 3) + v(n)
def s(k, t): return ln(k, t.encode())
def tensor(name, dims, kind, raw): return b''.join(i(1, d) for d in dims) + i(2, kind) + s(8, name) + ln(9, raw)
def node(op, ins, outs, attrs=()): return b''.join(s(1, x) for x in ins) + b''.join(s(2, x) for x in outs) + s(4, op) + b''.join(ln(5, a) for a in attrs)
def info(name, kind, dims): return s(1, name) + ln(2, ln(1, i(1, kind) + ln(2, b''.join(ln(1, i(1, d) if isinstance(d, int) else s(2, d)) for d in dims))))
def model(nodes, inits, ins, outs):
    g = b''.join(ln(1, n) for n in nodes) + s(2, 'g') + b''.join(ln(5, t) for t in inits) + b''.join(ln(11, x) for x in ins) + b''.join(ln(12, x) for x in outs)
    return i(1, 7) + s(2, 'sample') + ln(7, g) + ln(8, s(1, '') + i(2, 13))
def weights(name, rows, cols, seed): return tensor(name, [rows, cols], 1, np.random.default_rng(seed).random((rows, cols)).astype('float32').tobytes())
def zeros(out, shape, ins):
    value = s(1, 'value') + ln(5, tensor('', [1], 1, np.zeros(1, 'float32').tobytes())) + i(20, 4)
    return node('ConstantOfShape', [out + '_shape'], [out], [value]), tensor(out + '_shape', [len(shape)], 7, np.array(shape, 'int64').tobytes())
EOF_4
